#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

ll max(ll a, ll b) {
    return a > b ? a : b;
}

int main() {
    int N;
    ll K;
    scanf("%d %lld", &N, &K);

    int *P = malloc((N+1) * sizeof(int));
    int *C = malloc((N+1) * sizeof(int));

    for (int i = 1; i <= N; i++) scanf("%d", &P[i]);
    for (int i = 1; i <= N; i++) scanf("%d", &C[i]);

    int *visited = calloc(N+1, sizeof(int));
    ll ans = -1e18;

    for (int start = 1; start <= N; start++) {
        if (visited[start]) continue;

        // find cycle
        int cycle[3005];
        int len = 0;
        int cur = start;
        while (!visited[cur]) {
            visited[cur] = 1;
            cycle[len++] = cur;
            cur = P[cur];
        }

        ll cycle_sum = 0;
        for (int i = 0; i < len; i++) cycle_sum += C[cycle[i]];

        // try all starting positions in this cycle
        for (int s = 0; s < len; s++) {
            ll sum = 0;
            int steps = 0;
            for (int t = 0; t < len && t < K; t++) {
                int idx = (s + t) % len;
                sum += C[cycle[idx]];
                steps++;
                ans = max(ans, sum);
            }
            // if K is large enough for full cycles
            if (K > len && cycle_sum > 0) {
                ll full_cycles = K / len;
                ll rem = K % len;
                ll base = cycle_sum * (full_cycles - 1);
                // try one extra partial after full cycles
                ll best_partial = 0;
                ll run_sum = 0;
                for (int t = 0; t < len && t < rem + len; t++) {
                    int idx = (s + t) % len;
                    run_sum += C[cycle[idx]];
                    if (t < rem) best_partial = max(best_partial, run_sum);
                    else best_partial = max(best_partial, run_sum);
                }
                ans = max(ans, base + best_partial);
                // also just full cycles without extra partial
                ans = max(ans, cycle_sum * full_cycles);
            }
        }
    }

    printf("%lld\n", ans);

    free(P);
    free(C);
    free(visited);
    return 0;
}

