#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int N;
    ll K;
    if (scanf("%d %lld", &N, &K) != 2) return 0;

    int *P = (int *)malloc((N + 1) * sizeof(int));
    ll *C = (ll *)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N; i++) scanf("%d", &P[i]);
    for (int i = 1; i <= N; i++) scanf("%lld", &C[i]);

    char *used = (char *)calloc(N + 1, sizeof(char));
    ll answer = -(1LL << 60);

    for (int s = 1; s <= N; s++) {
        if (used[s]) continue;

        /* Extract one cycle */
        int cur = s;
        int m = 0;
        int *cyc = (int *)malloc((N + 1) * sizeof(int));
        while (!used[cur]) {
            used[cur] = 1;
            cyc[m++] = cur;
            cur = P[cur];
        }

        ll *val = (ll *)malloc(m * sizeof(ll));
        ll cycle_sum = 0;
        for (int i = 0; i < m; i++) {
            val[i] = C[cyc[i]];
            cycle_sum += val[i];
        }

        /* For each starting position in this cycle */
        for (int st = 0; st < m; st++) {
            ll prefix = 0;
            ll limit = (K < m ? K : m);
            for (ll step = 1; step <= limit; step++) {
                int idx = (st + step) % m;
                prefix += val[idx];

                ll cand = prefix;
                if (cycle_sum > 0) {
                    ll extra = (K - step) / m;
                    cand += cycle_sum * extra;
                }
                answer = maxll(answer, cand);
            }
        }

        free(val);
        free(cyc);
    }

    printf("%lld\n", answer);

    free(used);
    free(P);
    free(C);
    return 0;
}

