int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 K;
    cin >> N >> K;
    vector<int> P(N);
    vector<int64> C(N);
    for (int i = 0; i < N; i++) {
        cin >> P[i];
        P[i]--;
    }
    for (int i = 0; i < N; i++) {
        cin >> C[i];
    }

    vector<bool> visited(N, false);
    int64 ans = -1e18;

    for (int i = 0; i < N; i++) {
        if (visited[i]) continue;
        vector<int> cycle;
        int cur = i;
        while (!visited[cur]) {
            visited[cur] = true;
            cycle.push_back(cur);
            cur = P[cur];
        }

        int M = cycle.size();
        // For each start in cycle, compute best
        for (int startIdx = 0; startIdx < M; startIdx++) {
            int64 sum = 0;
            int steps = 0;
            // We can take up to K steps, but we cannot exceed M per loop check
            int limit = min((int64)M, K);
            // First pass: try up to min(K, M) steps without full cycle
            for (int t = 0; t < limit; t++) {
                int pos = cycle[(startIdx + t) % M];
                sum += C[pos];
                steps++;
                ans = max(ans, sum);
                if (t + 1 == K) break;
            }
            if (K > M) {
                int64 cycleSum = 0;
                for (int v : cycle) cycleSum += C[v];
                if (cycleSum > 0) {
                    // We can take full cycles
                    int64 base = sum; // sum after first M steps from this start
                    int64 fullCycles = (K - M) / M;
                    int64 extraSteps = (K - M) % M;
                    // Option: take fullCycles more cycles and then extra steps
                    int64 curSum = base + fullCycles * cycleSum;
                    ans = max(ans, curSum);
                    // Then take extra steps
                    int64 add = 0;
                    for (int t = 0; t < extraSteps; t++) {
                        int pos = cycle[(startIdx + M + t) % M];
                        add += C[pos];
                        ans = max(ans, curSum + add);
                    }
                    // Also consider: maybe take (fullCycles+1) cycles then stop earlier
                    int64 curSum2 = base + (fullCycles + 1) * cycleSum;
                    ans = max(ans, curSum2);
                    // And take partial after that
                    int64 add2 = 0;
                    for (int t = 0; t < M; t++) {
                        int pos = cycle[(startIdx + M + t) % M];
                        add2 += C[pos];
                        ans = max(ans, curSum2 + add2);
                    }
                } else {
                    // cycle sum <= 0, no point going full cycle, already tried up to M steps
                }
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

