int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, K;
    cin >> N >> K;

    vector<long long> C(N+1);
    for(int i = 1; i <= N; i++) cin >> C[i];

    vector<int> P(N+1);
    for(int i = 1; i <= N; i++){
        cin >> P[i];
    }

    vector<bool> visited(N+1, false);
    long long ans = 0;

    for(int start = 1; start <= N; start++){
        if(visited[start]) continue;

        // Trace the cycle
        vector<int> cycle;
        int cur = start;
        while(!visited[cur]){
            visited[cur] = true;
            cycle.push_back(cur);
            cur = P[cur];
        }

        int L = cycle.size();
        // Compute prefix sums of C[cycle[1]], C[cycle[2]], ... (after moving)
        // Moving from cycle[i] goes to cycle[(i+1)%L], gaining C[cycle[(i+1)%L]]
        // So starting at cycle[i], after r moves, score = sum of C[cycle[(i+1)%L]], ..., C[cycle[(i+r)%L]]

        // Total cycle sum
        long long S = 0;
        for(int i = 0; i < L; i++) S += C[cycle[i]];

        // For each starting position in cycle, compute best score
        // Double the cycle for easy prefix computation
        vector<long long> vals(2*L);
        for(int i = 0; i < 2*L; i++) vals[i] = C[cycle[i % L]];

        vector<long long> prefix(2*L+1, 0);
        for(int i = 0; i < 2*L; i++) prefix[i+1] = prefix[i] + vals[i];

        for(int i = 0; i < L; i++){
            // Starting at cycle[i], first move goes to cycle[(i+1)%L]
            // After r moves (1 <= r <= min(K, ...)), score = prefix sum of r elements starting at index (i+1)%L
            // = prefix[(i+1)%L + r] - prefix[(i+1)%L]  (in doubled array)
            int base = (i+1) % L; // index in cycle of first gained element
            // In doubled array, elements from base to base+r-1
            for(int r = 0; r <= min(K, L-1); r++){
                long long score;
                if(r == 0){
                    score = 0;
                } else {
                    score = prefix[base + r] - prefix[base];
                }
                // Add full loops if beneficial
                if(S > 0 && r <= K){
                    long long remaining = K - r;
                    long long loops = remaining / L;
                    score += loops * S;
                }
                ans = max(ans, score);
            }
        }
    }

    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long K;
    cin >> N >> K;

    vector<int> P(N);
    for (int i = 0; i < N; i++) {
        cin >> P[i];
        --P[i];
    }

    vector<ll> C(N);
    for (int i = 0; i < N; i++) cin >> C[i];

    const ll NEG = -(1LL << 60);
    ll ans = NEG;

    for (int s = 0; s < N; s++) {
        vector<ll> seq;
        int cur = s;
        ll cycle_sum = 0;

        do {
            cur = P[cur];
            seq.push_back(C[cur]);
            cycle_sum += C[cur];
        } while (cur != s);

        int L = (int)seq.size();

        // Try taking t moves within at most one cycle first.
        vector<ll> pref(2 * L + 1, 0);
        for (int i = 0; i < 2 * L; i++) pref[i + 1] = pref[i] + seq[i % L];

        for (int t = 1; t <= min<long long>(K, L); t++) {
            ans = max(ans, pref[t]);
        }

        // If cycle sum is positive, full extra cycles may help.
        if (cycle_sum > 0) {
            for (int t = 1; t <= min<long long>(K, L); t++) {
                ll rem = K - t;
                ll full = rem / L;
                ans = max(ans, pref[t] + full * cycle_sum);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

