                    // also consider: if cycleSum > 0, add extra full cycles
                    if (cycleSum > 0) {
                        long len = j + 1;
                        long extra = ((K - len) / L) * cycleSum;
                        ans = Math.max(ans, sum + extra);
                    } else {
                        ans = Math.max(ans, sum);
                    }
                }
            }
        }
        System.out.println(ans);
    }
