import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long K = fs.nextLong();

        int[] P = new int[N];
        for (int i = 0; i < N; i++) P[i] = fs.nextInt() - 1;

        long[] C = new long[N];
        for (int i = 0; i < N; i++) C[i] = fs.nextLong();

        boolean[] visited = new boolean[N];
        long answer = Long.MIN_VALUE;

        for (int i = 0; i < N; i++) {
            if (visited[i]) continue;

            // Extract one cycle
            List<Integer> cycleNodes = new ArrayList<>();
            int cur = i;
            while (!visited[cur]) {
                visited[cur] = true;
                cycleNodes.add(cur);
                cur = P[cur];
            }

            int L = cycleNodes.size();
            long[] vals = new long[L];
            long cycleSum = 0;
            for (int j = 0; j < L; j++) {
                vals[j] = C[cycleNodes.get(j)];
                cycleSum += vals[j];
            }

            // For each starting position in this cycle
            for (int s = 0; s < L; s++) {
                long prefix = 0;
                int maxStep = (int) Math.min(K, L);
                for (int t = 1; t <= maxStep; t++) {
                    prefix += vals[(s + t - 1) % L];
                    long score = prefix;

                    if (cycleSum > 0 && K > t) {
                        long extraCycles = (K - t) / L;
                        score += extraCycles * cycleSum;
                    }

                    answer = Math.max(answer, score);
                }
            }
        }

        System.out.println(answer);
    }
}
